import math

state = {'step': 0}

def control(obs):
    state['step'] += 1
    t = obs['t']
    # Scan left-back then right-back while starting slow reverse
    if state['step'] <= 8:
        look = 160.0
    else:
        look = -160.0

    views = obs.get('views', {})
    if 'direct' in views and views['direct'].get('walls'):
        ox, oy = views['direct']['origin']
        pts = []
        for b, d in views['direct']['walls']:
            rad = math.radians(b)
            wx = ox + d * math.cos(rad)
            wy = oy + d * math.sin(rad)
            pts.append((round(wx, 1), round(wy, 1)))
        print(f"t={t:.1f} gaze={obs['head']['gaze_deg']:.0f} pts={pts}")
    if obs.get('target', {}).get('in_sight'):
        print(f"TARGET: {obs['target']}")

    # Keep trailer straight while slowly reversing
    hitch = obs['hitch_deg']
    steer = max(-45.0, min(45.0, 2.0 * hitch))
    return (steer, -0.3, look)

