import math

state = {'step': 0, 'printed': set()}

def control(obs):
    state['step'] += 1
    t = obs['t']
    s = state['step']
    if s <= 15:
        look = 64.0
        tag = 'L_mir'
    elif s <= 35:
        look = -64.0
        tag = 'R_mir'
    else:
        look = -140.0
        tag = 'R_back'

    views = obs.get('views', {})
    if obs['head']['settled'] and tag not in state['printed']:
        state['printed'].add(tag)
        for vname in ('direct', 'left_mirror', 'right_mirror'):
            v = views.get(vname)
            if v and (v.get('walls') or v.get('target_corners')):
                ox, oy = v['origin']
                pts = []
                for b, d in v.get('walls', []):
                    rad = math.radians(b)
                    wx = ox + d * math.cos(rad)
                    wy = oy + d * math.sin(rad)
                    pts.append((round(wx, 1), round(wy, 1)))
                print(f"t={t:.1f} {tag} {vname} orig=({ox:.2f},{oy:.2f}) pts={pts}")

    hitch = obs['hitch_deg']
    steer = max(-45.0, min(45.0, 2.5 * hitch))
    return (steer, -0.6, look)

